#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    int x = *(int*)a, y = *(int*)b;
    return x - y;
}

int check(int *a, int n) {
    if (n == 1) return 1;
    int half = n / 2;
    for (int i = 0; i < half; i++) {
        if (a[i] >= a[i + half]) return 0;
    }
    if (!check(a, half)) return 0;
    if (!check(a + half, half)) return 0;
    return 1;
}

int main() {
    int n;
    scanf("%d", &n);
    int sz = 1 << n;
    int *a = malloc(sz * sizeof(int));
    for (int i = 0; i < sz; i++) scanf("%d", &a[i]);
    qsort(a, sz, sizeof(int), cmp);
    printf("%s\n", check(a, sz) ? "Yes" : "No");
    free(a);
    return 0;
}

