int compare(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int main() {
    int n;
    scanf("%d", &n);
    int size = 1 << n;
    int *arr = malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) {
        scanf("%d", &arr[i]);
    }
    qsort(arr, size, sizeof(int), compare);

    // count frequencies
    int *vals = malloc(size * sizeof(int));
    int *freq = malloc(size * sizeof(int));
    int unique = 0;
    vals[0] = arr[0];
    freq[0] = 1;
    for (int i = 1; i < size; i++) {
        if (arr[i] == vals[unique]) {
            freq[unique]++;
        } else {
            unique++;
            vals[unique] = arr[i];
            freq[unique] = 1;
        }
    }
    unique++;

    long long carry = 0;
    for (int i = 0; i < unique; i++) {
        long long total = freq[i] + carry;
        if (total % 2 != 0) {
            printf("NO\n");
            free(arr);
            free(vals);
            free(freq);
            return 0;
        }
        carry = total / 2;
    }

    if (carry == 1) {
        printf("YES\n");
    } else {
        printf("NO\n");
    }

    free(arr);
    free(vals);
    free(freq);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static int cmp_ll(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int M = 1 << N;
    long long *a = (long long *)malloc((size_t)M * sizeof(long long));
    if (!a) return 0;

    for (int i = 0; i < M; i++) scanf("%lld", &a[i]);

    qsort(a, M, sizeof(long long), cmp_ll);

    /* used[i] = 1 if a[i] is already chosen into the current set of parents */
    char *used = (char *)calloc((size_t)M, sizeof(char));
    int *cur = (int *)malloc((size_t)M * sizeof(int));
    int *next = (int *)malloc((size_t)M * sizeof(int));
    if (!used || !cur || !next) return 0;

    /* The initial slime must be the maximum element. */
    used[M - 1] = 1;
    cur[0] = M - 1;
    int cur_sz = 1;

    for (int step = 0; step < N; step++) {
        int need = cur_sz;
        int p = cur_sz - 1;   /* process current parents from smallest to largest */
        int next_sz = 0;

        for (int i = M - 1; i >= 0 && need > 0; i--) {
            if (used[i]) continue;
            if (a[i] < a[cur[p]]) {
                used[i] = 1;
                next[next_sz++] = i;
                p--;
                need--;
            }
        }

        if (need > 0) {
            printf("No\n");
            free(a); free(used); free(cur); free(next);
            return 0;
        }

        for (int i = 0; i < next_sz; i++) cur[cur_sz + i] = next[i];
        cur_sz += next_sz;

        qsort(cur, (size_t)cur_sz, sizeof(int), 
            (int (*)(const void *, const void *))[](const int *x, const int *y) {
                return (*x > *y) - (*x < *y);
            }
        );
    }

    printf("Yes\n");

    free(a);
    free(used);
    free(cur);
    free(next);
    return 0;
}

