        int[] a = new int[size];
        for (int i = 0; i < size; i++) {
            a[i] = sc.nextInt();
        }
        Arrays.sort(a);
        // Reverse to get descending
        for (int i = 0; i < size / 2; i++) {
            int tmp = a[i]; a[i] = a[size-1-i]; a[size-1-i] = tmp;
        }
        boolean ok = true;
        for (int i = 0; i < size; i++) {
            if (2*i+1 < size && a[i] <= a[2*i+1]) { ok = false; break; }
            if (2*i+2 < size && a[i] <= a[2*i+2]) { ok = false; break; }
        }
        System.out.println(ok ? "Yes" : "No");
    }
}

