public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        int size = 1 << N;
        String[] parts = br.readLine().trim().split(" ");
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        for (int i = 0; i < size; i++) {
            pq.add(Integer.parseInt(parts[i]));
        }

        while (pq.size() > 1) {
            int largest = pq.poll();
            // Find any element smaller than largest
            PriorityQueue<Integer> temp = new PriorityQueue<>(Collections.reverseOrder());
            boolean found = false;
            while (!pq.isEmpty()) {
                int cur = pq.poll();
                if (!found && cur < largest) {
                    found = true;
                    // largest remains (parent), cur is removed (offspring)
                    // we do nothing with cur
                } else {
                    temp.add(cur);
                }
            }
            if (!found) {
                System.out.println("No");
                return;
            }
            pq.add(largest);
            pq.addAll(temp);
        }
        System.out.println("Yes");
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int m = 1 << N;
        int[] a = new int[m];
        for (int i = 0; i < m; i++) a[i] = fs.nextInt();

        Arrays.sort(a);

        // dp[i] = number of available "parents" among first i processed elements
        // after greedily assigning each next element either as a root/new available parent
        // or as a child consuming one available parent.
        //
        // Process from largest to smallest.
        // Largest element must be the initial slime.
        int available = 1; // the largest slime can be a parent
        int used = 1;

        int i = m - 2;
        while (i >= 0) {
            int j = i;
            while (j >= 0 && a[j] == a[i]) j--;
            int cnt = i - j; // number of equal values in this group

            // All slimes of this health must be children of strictly larger slimes,
            // because equal health cannot parent each other.
            if (cnt > available) {
                System.out.println("No");
                return;
            }

            // They consume cnt available parents, and themselves become cnt new available parents.
            // Net available stays the same.
            used += cnt;
            i = j;
        }

        // Need exactly 2^N slimes, and if all groups were assignable then construction is possible.
        System.out.println(used == m ? "Yes" : "No");
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

