int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    int M = 1 << N;

    vector<long long> a(M);
    for (int i = 0; i < M; ++i) cin >> a[i];

    sort(a.begin(), a.end());

    // We build levels from largest to smallest.
    // cur = slimes that already have assigned parents among larger values
    // and therefore can reproduce in the remaining steps.
    multiset<long long> cur;
    cur.insert(a.back()); // root must be the maximum

    for (int i = M - 2; i >= 0; --i) {
        auto it = cur.upper_bound(a[i]); // need a parent strictly greater
        if (it == cur.end()) {
            cout << "No\n";
            return 0;
        }
        cur.insert(a[i]);
    }

    cout << "Yes\n";
    return 0;
}
